// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function testFuzz_property(address caller, uint256 contractBalance, uint256 recipientAmount) public {
        vm.assume(caller != address(this));
        vm.assume(contractBalance > 0);
        vm.deal(address(c), contractBalance);
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        try c.withdrawAll(address(this)) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore);
        } catch {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}
